// Custom Worker entry: wraps the OpenNext (Next.js) handler and adds the admin
// dashboard backend (a Durable Object) plus the 5-minute cron that publishes
// scheduled posts, sends outreach emails and checks for replies.
// @ts-ignore `.open-next/worker.js` is generated by `npm run build`
import { default as nextHandler } from "./.open-next/worker.js";
import type { Env } from "./worker/store";

export { AdminStore } from "./worker/store";

const store = (env: Env) => env.ADMIN_STORE.get(env.ADMIN_STORE.idFromName("main"));

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const { pathname } = new URL(request.url);
    if (pathname.startsWith("/api/admin/") || pathname === "/api/lead" || pathname === "/api/hooks/cal") {
      return store(env).fetch(request);
    }
    return nextHandler.fetch(request, env, ctx);
  },
  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext): Promise<void> {
    ctx.waitUntil(store(env).tick());
  },
} satisfies ExportedHandler<Env>;
